NOTES=[
N('You like pizza, ___?',"don't you","Present Simple cümlede yardımcı fiil yoktur, bu yüzden tag do ile kurulur. Olumlu cümle olduğu için tag olumsuz olur: don't you?",{"aren't you":"Tag, cümledeki yardımcı fiili tekrar eder; 'like' ile are değil do kullanılır: don't you.", "didn't you":"Cümle Present Simple (like); tag'de de Present Simple yardımcı fiili (do) gerekir, did geçmiş zamandır."}),
N('She is a doctor, ___?',"isn't she","Cümlede be fiili (is) olduğu için tag'de de be kullanılır; özne She olduğu için zamir she, cümle olumlu olduğu için tag olumsuzdur: isn't she?",{"doesn't she":"Cümlede be fiili (is) var; tag da be ile kurulur. doesn't, 'does' yardımcı fiilini gerektiren cümlelere aittir.", "isn't he":"Zamir özneyle uymalı: She → she. 'he' farklı bir kişiyi gösterir."}),
N('They went to the park, ___?',"didn't they","Past Simple cümlede (went) yardımcı fiil yoktur; tag'de did kullanılır. Cümle olumlu olduğu için tag olumsuz: didn't they?",{"don't they":"Cümle Past Simple (went); tag'de did gerekir. don't Present Simple içindir.", "weren't they":"'went' bir hareket fiilidir, be fiili değil; tag'de were kullanılmaz, did gerekir."}),
N("He can't swim, ___?",'can he',"Cümle olumsuz (can't) olduğu için tag olumlu olur ve aynı modal tekrar edilir: can he?",{"can't he":"Olumsuz cümleden sonra tag olumlu olur; can't he iki tarafı da olumsuz yapar.", 'does he':"Cümledeki yardımcı fiil modal can'dir; tag'de can tekrar edilir, does değil."}),
N("We aren't late, ___?",'are we',"Cümle olumsuz (aren't) olduğu için tag olumlu: are we? Be fiili tag'de tekrar edilir.",{"aren't we":"Olumsuz cümleden sonra tag olumlu olmalı; aren't we çift olumsuz olur.", 'do we':"Cümlede be fiili (are) var; tag'de de be tekrar edilir, do değil."}),
N("It's cold today, ___?","isn't it","It's, it is demektir. Be fiili tekrar edilir ve olumlu cümle olduğu için tag olumsuz olur: isn't it?",{"doesn't it":"Cümlede It's = It is (be fiili) var; tag be ile kurulur, does ile değil.", "isn't that":"Tag'de zamir cümlenin öznesini tekrar eder (it). that tag'de kullanılmaz."}),
N('I love jazz. — So ___ I.','do','Ben de demek için so + yardımcı fiil + özne kullanılır. Yardımcı fiil, ilk cümledeki zamanla uyumlu olmalı: love → do.',{'am':'So + yardımcı fiil: ilk cümlede love (Present Simple) var, yardımcı fiil do olmalı; am be fiilidir.', 'did':'love şimdiki/genel zaman; did geçmiş zamandır ve zaman uyumsuzluğu yaratır.'}),
N("I don't like coffee. — Neither ___ I.",'do','Neither kelimesi olumsuzluğu taşır; yardımcı fiil olumlu yazılır ve ilk cümleyle uyumludur: Neither do I.',{"don't":'Neither zaten olumsuzdur; arkasına olumsuz yardımcı fiil eklenmez (çift olumsuzluk).', 'am':'Ilk cümlede like (Present Simple) var; yardımcı fiil do olmalı, am değil.'}),
N('I have finished my work. — So ___ I.','have','Cevaptaki yardımcı fiil ilk cümledekiyle aynı olur: have finished → So have I.',{'do':'İlk cümlede have finished (Present Perfect) var; yardımcı fiil have olmalı, do değil.', 'am':"am, be fiilidir; Present Perfect'te yardımcı fiil have / has'tir."}),
N('I am hungry, ___?',"aren't I","I am cümlesinin tag'i özel bir kalıptır: aren't I? (amn't I denmez).",{"amn't I":"Standart İngilizcede amn't kullanılmaz; I am için tag aren't I'dır.", "don't I":"Cümlede be fiili (am) var; tag'de do kullanılmaz."}),
N("Let's go out tonight, ___?",'shall we',"Let's ile kurulan öneri cümlelerinin tag'i shall we'dir.",{'will we':"Let's için tag will we değil, shall we'dir.", 'let we':"Tag'de 'let' tekrar edilmez; yardımcı fiil + zamir gerekir."}),
N('Open the window, ___?','will you',"Emir cümlelerinden sonra tag olarak will you (ya da won't you) kullanılır.",{'do you':"Emir cümlesinin tag'i will you olur; do you bu yapıda kullanılmaz.", 'shall we':"shall we yalnızca Let's cümlelerinde kullanılır."}),
N('Hangi cümle doğru?',"There is a bank near here, isn't there?","There is / there are cümlelerinde tag'de de there kullanılır: isn't there?",{"There is a bank near here, isn't it?":"there is kalıbında özne gibi davranan there, tag'de de there olarak tekrar edilir; it kullanılmaz.", "There is a bank near here, doesn't it?":"Cümlede be fiili (is) var; tag'de does kullanılmaz."}),
N('Hangi cümle doğru?','Nobody called, did they?','Nobody olumsuz bir kelimedir; tag olumlu (did) ve kişi için they kullanılır: Nobody called, did they?',{"Nobody called, didn't they?":'Nobody olumsuz anlamlıdır, cümle zaten olumsuz sayılır; tag olumlu olmalıdır.', 'Nobody called, did it?':"Nobody gibi belirsiz kişi zamirlerinden sonra tag'de they kullanılır, it değil."}),
N("I can't drive. — ___",'Neither can I.',"Olumsuz cümleye 'ben de' demek için Neither + aynı modal + özne kullanılır: Neither can I.",{'So can I.':"Olumsuz cümleye (can't) 'So can I' ile karşılık verilmez; anlam ters çıkar. Neither gerekir.", 'Neither I can.':"Neither'dan sonra yardımcı fiil özneden önce gelir: Neither can I."}),
N('Hangi cümle doğru?',"You've seen the film, haven't you?","You've seen = You have seen. Yardımcı fiil have, tag'de de have olur: haven't you?",{"You've seen the film, don't you?":"Cümlede have (Present Perfect) var; tag'de do değil have gerekir.", "You've seen the film, aren't you?":"You've = You have; tag'de be (are) kullanılmaz, have tekrar edilir."}),
N('Hangi cümle "Ben de" anlamındadır? → I work hard.','So do I.','So do I: so + yardımcı fiil + özne. İlk cümle Present Simple olduğu için yardımcı fiil do.',{'So am I.':'İlk cümlede work (Present Simple) var; yardımcı fiil do olmalı, am değil.', 'So I work.':"So'dan sonra yardımcı fiil özneden önce gelir (So do I). So I work, ters sıra yüzünden 'Ben de' anlamı vermez."}),
N('Hangi cümle doğru?','She hardly ever complains, does she?','hardly ever, rarely, never gibi kelimeler cümleyi olumsuz yapar; tag olumlu olur: does she?',{"She hardly ever complains, doesn't she?":'hardly ever olumsuz anlamlıdır; tag olumlu olmalıdır (does she).', 'She hardly ever complains, is she?':"Cümle complains (Present Simple); tag'de do/does gerekir, is değil."}),
N('Hangi cümle doğru?','Nothing happened, did it?',"Nothing olumsuz bir kelimedir ve şey anlamına geldiği için tag'de it kullanılır: did it?",{"Nothing happened, didn't it?":'Nothing olumsuz anlamlıdır; tag olumlu olmalıdır.', 'Nothing happened, did they?':"Nothing (şey) için tag'de it kullanılır; they kişiler içindir (nobody / everybody)."}),
N('Hangi cümle doğru?',"I used to live here, didn't I?","used to + yalın fiil yapısında tag, did ile kurulur: didn't I?",{"I used to live here, usedn't I?":"used to'nun tag'i modern İngilizcede did kullanılarak kurulur; usedn't I çok nadir/eski kullanımdır.", "I used to live here, wasn't I?":"used to bir be yapısı değildir; tag'de was kullanılmaz."}),
]
